import Dashboard from '../Dashboard/Dashboard';
import Leads from '../Leads/Leads';
import Properties from '../Properties/Properties';
import Projects from '../Projects/Projects';
import Customers from '../Customers/Customers';
import SiteVisits from '../SiteVisits/SiteVisits';
import Bookings from '../Bookings/Bookings';
import Payments from '../Payments/Payments';
import Employees from '../Employees/Employees';
import Attendance from '../Attendance/Attendance';
import Payroll from '../Payroll/Payroll';
import FollowUps from '../FollowUps/FollowUps';
import WhatsApp from '../WhatsApp/WhatsApp';
import Reports from '../Reports/Reports';
import Settings from '../Settings/Settings';

const pageRoutes = [
  { name: 'Dashboard', path: '/dashboard', component: Dashboard, roles: ['owner','employee'] },
  { name: 'Leads', path: '/leads', component: Leads, roles: ['owner','employee'] },
  { name: 'Properties', path: '/properties', component: Properties, roles: ['owner','employee'] },
  { name: 'Projects', path: '/projects', component: Projects, roles: ['owner','employee'] },
  { name: 'Customers', path: '/customers', component: Customers, roles: ['owner','employee'] },
  { name: 'Site Visits', path: '/site-visits', component: SiteVisits, roles: ['owner','employee'] },
  { name: 'Bookings', path: '/bookings', component: Bookings, roles: ['owner','employee'] },
  { name: 'Payments', path: '/payments', component: Payments, roles: ['owner'] },
  { name: 'Employees', path: '/employees', component: Employees, roles: ['owner'] },
  { name: 'Attendance', path: '/attendance', component: Attendance, roles: ['owner','employee'] },
  { name: 'Payroll', path: '/payroll', component: Payroll, roles: ['owner'] },
  { name: 'Follow-ups', path: '/follow-ups', component: FollowUps, roles: ['owner','employee'] },
  { name: 'WhatsApp', path: '/whatsapp', component: WhatsApp, roles: ['owner','employee'] },
  { name: 'Reports', path: '/reports', component: Reports, roles: ['owner'] },
  { name: 'Settings', path: '/settings', component: Settings, roles: ['owner'] },
];

export default pageRoutes;
